// Archive.org search queries for Arabic-dubbed public domain films
const queries = [
  { q: 'subject:(arabic dubbed) mediatype:movies', lang: 'ar_dubbed', origin: 'american' },
  { q: 'collection:feature_films subject:(arabic) mediatype:movies', lang: 'ar_dubbed', origin: 'american' },
  { q: 'subject:(مدبلج) mediatype:movies', lang: 'ar_dubbed', origin: 'other' },
  { q: 'subject:(فيلم عربي) mediatype:movies', lang: 'ar_dubbed', origin: 'moroccan' },
  { q: 'collection:opensource_movies subject:(bollywood arabic) mediatype:movies', lang: 'ar_dubbed', origin: 'indian' }
];
return queries.map(q => ({ json: q }));

const body = $input.first().json;
const query = $('Generate Queries').item.json;
const docs = body?.response?.docs || [];

const MIN_RUNTIME_SEC = 3000; // ~50 min minimum

function parseRuntime(r) {
  if (!r) return 0;
  if (typeof r === 'number') return r;
  const s = String(r);
  // HH:MM:SS or MM:SS
  const parts = s.split(':').map(Number);
  if (parts.length === 3) return parts[0]*3600 + parts[1]*60 + parts[2];
  if (parts.length === 2) return parts[0]*60 + parts[1];
  return parseInt(s) || 0;
}

const films = docs
  .filter(d => d.identifier && d.title)
  .map(d => {
    const dur = parseRuntime(d.runtime);
    return {
      identifier: d.identifier,
      ytId: 'arc_' + d.identifier,
      title: d.title,
      year: d.year ? parseInt(d.year) : null,
      duration_sec: dur || null,
      lang: query.lang || 'ar_dubbed',
      origin: query.origin || 'other',
      rating: d.avg_rating || null
    };
  })
  .filter(d => !d.duration_sec || d.duration_sec >= MIN_RUNTIME_SEC);

console.log(`[Archive.org] ${query.q} → ${films.length} films`);
return [{ json: { films, query: query.q } }];

const filmList = $input.first().json.films || [];
const queryLabel = $input.first().json.query || 'archive.org';
const API_URL = 'https://mawso3a-stream.vercel.app/api/import';
const SECRET = process.env.N8N_SECRET;

let imported = 0, skipped = 0, errors = 0;

for (const f of filmList) {
  try {
    const r = await fetch(`${API_URL}?action=import-film`, {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${SECRET}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        ytId:         f.ytId,
        title_ar:     f.title,
        origin:       f.origin,
        language:     f.lang,
        year:         f.year,
        duration_sec: f.duration_sec,
        source:       'archive.org'
      })
    });
    const data = await r.json().catch(() => ({ ok: false }));
    data.ok ? imported++ : (r.status === 409 ? skipped++ : errors++);
  } catch(e) {
    console.error('Archive import error:', f.identifier, e.message);
    errors++;
  }
}

// Log to discovery_log
await fetch(`${API_URL}?action=log`, {
  method: 'POST',
  headers: { 'Authorization': `Bearer ${SECRET}`, 'Content-Type': 'application/json' },
  body: JSON.stringify({ query: `archive.org: ${queryLabel}`, found: filmList.length, imported, skipped })
}).catch(() => {});

console.log(`[Archive.org] DONE: ${imported} imported, ${skipped} skipped, ${errors} errors`);
return [{ json: { imported, skipped, errors } }];
